-- Dictionary: loads word lists from ServerStorage.Words (generated by build.py),
-- validates words, searches for legal moves, and filters words through TextService.
local ServerStorage = game:GetService("ServerStorage")
local TextService = game:GetService("TextService")
local RunService = game:GetService("RunService")

local Shared = game:GetService("ReplicatedStorage"):WaitForChild("Shared")
local Config = require(Shared.Config)
local WordRules = require(Shared.WordRules)

local Dictionary = {}

local sets = {} -- [length] = { [word] = true }
local lists = {} -- [length] = { word, ... }
local ALPHABET = "abcdefghijklmnopqrstuvwxyz"

for _, mod in ipairs(ServerStorage:WaitForChild("Words"):GetChildren()) do
	if mod:IsA("ModuleScript") then
		local blob = require(mod)
		for w in string.gmatch(blob, "%a+") do
			local len = #w
			sets[len] = sets[len] or {}
			lists[len] = lists[len] or {}
			if not sets[len][w] then
				sets[len][w] = true
				table.insert(lists[len], w)
			end
		end
	end
end

function Dictionary.IsWord(word)
	local s = sets[#word]
	return s ~= nil and s[word] == true
end

-- banned = { [index] = letter } : letters a player may not put back this turn
local function violatesBan(word, banned)
	if not banned then
		return false
	end
	for idx, ch in pairs(banned) do
		if word:sub(idx, idx) == ch then
			return true
		end
	end
	return false
end
Dictionary.ViolatesBan = violatesBan

-- Finds words exactly `diffs` letters away from `word` that are unused and not banned.
-- Stops after `limit` results (nil = all). Returns list.
function Dictionary.Moves(word, diffs, used, banned, limit)
	local out = {}
	local len = #word
	local set = sets[len]
	if not set then
		return out
	end
	limit = limit or math.huge

	local chars = {}
	for i = 1, len do
		chars[i] = word:sub(i, i)
	end

	local function consider()
		local cand = table.concat(chars)
		if set[cand] and not (used and used[cand]) and not violatesBan(cand, banned) then
			table.insert(out, cand)
		end
		return #out >= limit
	end

	-- recursive choose `diffs` positions, each set to a different letter
	local function rec(startIdx, remaining)
		if remaining == 0 then
			return consider()
		end
		for i = startIdx, len - remaining + 1 do
			local orig = chars[i]
			for k = 1, 26 do
				local ch = ALPHABET:sub(k, k)
				if ch ~= orig then
					chars[i] = ch
					if rec(i + 1, remaining - 1) then
						chars[i] = orig
						return true
					end
				end
			end
			chars[i] = orig
		end
		return false
	end

	rec(1, diffs)
	return out
end

function Dictionary.HasMove(word, diffs, used, banned)
	return #Dictionary.Moves(word, diffs, used, banned, 1) > 0
end

-- Smallest number of changed letters (1..3) that still has a legal move, or nil.
function Dictionary.MinEscape(word, used, banned)
	for d = 1, math.min(3, #word) do
		if Dictionary.HasMove(word, d, used, banned) then
			return d
		end
	end
	return nil
end

function Dictionary.IsRare(word)
	return WordRules.IsRare(word, Config.RareLetters)
end

---------------------------------------------------------------- chat-safety filter
-- Every word shown to other players goes through Roblox text filtering once, then is cached.
local filterCache = {}
function Dictionary.IsAllowed(word, userId)
	local cached = filterCache[word]
	if cached ~= nil then
		return cached
	end
	if RunService:IsStudio() then
		return true -- filtering is a no-op in Studio
	end
	local ok, result = pcall(function()
		local res = TextService:FilterStringAsync(word, userId or 1)
		return res:GetNonChatStringForBroadcastAsync()
	end)
	if not ok then
		return true -- filter outage: do not block play; result not cached so it retries later
	end
	local allowed = (string.lower(result) == word)
	filterCache[word] = allowed
	return allowed
end

-- Common everyday start words (generated from words_start.txt), keyed by length.
local startLists = {}
local commonSet = {} -- [word] = true for everyday words
do
	local mod = ServerStorage:FindFirstChild("StartWords")
	if mod and mod:IsA("ModuleScript") then
		for len, blob in pairs(require(mod)) do
			local l = {}
			sets[len] = sets[len] or {}
			lists[len] = lists[len] or {}
			for w in string.gmatch(blob, "%a+") do
				-- start words are always playable, even if the big list lacks them
				if not sets[len][w] then
					sets[len][w] = true
					table.insert(lists[len], w)
				end
				table.insert(l, w)
				commonSet[w] = true
			end
			startLists[len] = l
		end
	end
	-- everyday words (start words + popular.txt): bot moves and Help hints prefer these
	local commonMod = ServerStorage:FindFirstChild("CommonWords")
	if commonMod and commonMod:IsA("ModuleScript") then
		for len, blob in pairs(require(commonMod)) do
			for w in string.gmatch(blob, "%a+") do
				if sets[len] and sets[len][w] then
					commonSet[w] = true
				end
			end
		end
	end
end

-- Random start word: a common word with at least 3 one-letter moves and no rare letters.
-- Falls back to the full dictionary only if the common list has nothing usable.
function Dictionary.StartWord(len)
	local common = startLists[len]
	if common and #common > 0 then
		for _ = 1, 100 do
			local w = common[math.random(1, #common)]
			if not Dictionary.IsRare(w) and #Dictionary.Moves(w, 1, nil, nil, 3) >= 3 and Dictionary.IsAllowed(w) then
				return w
			end
		end
	end
	local list = lists[len] or lists[4]
	for _ = 1, 300 do
		local w = list[math.random(1, #list)]
		if not Dictionary.IsRare(w) and #Dictionary.Moves(w, 1, nil, nil, 3) >= 3 and Dictionary.IsAllowed(w) then
			return w
		end
	end
	return list[1]
end

-- the hand-picked everyday words of a given length (start words, daily ladder ends)
function Dictionary.StartList(len)
	return startLists[len] or {}
end

function Dictionary.IsCommon(word)
	return commonSet[word] == true
end

-- One legal move for the bot or a Help hint. Prefers everyday words so players
-- are not shown obscure Scrabble words; falls back to any allowed word.
function Dictionary.PickMove(word, diffs, used, banned)
	local moves = Dictionary.Moves(word, diffs, used, banned, diffs == 1 and nil or 200)
	local common, other = {}, {}
	for _, w in ipairs(moves) do
		table.insert(commonSet[w] and common or other, w)
	end
	for _, pool in ipairs({ common, other }) do
		while #pool > 0 do
			local i = math.random(#pool)
			if Dictionary.IsAllowed(pool[i]) then
				return pool[i]
			end
			table.remove(pool, i)
		end
	end
	return nil
end

function Dictionary.AllWords(len)
	return lists[len] or {}
end

function Dictionary.Count()
	local n = 0
	for _, l in pairs(lists) do
		n += #l
	end
	return n
end

return Dictionary
